const b = $input.first().json.body || {};
const ip = String(b.ip || '').trim();
const WHITELIST = ['127.0.0.1', '::1'];
const validIp = /^(\d{1,3}\.){3}\d{1,3}$/.test(ip) || ip.includes(':');

let raw = [b.path, b.query, b.payload, b.user_agent].filter(Boolean).join(' ');
try { raw = decodeURIComponent(raw); } catch (e) {}

const RULES = [
  { type: 'sql_injection',     severity: 'high',     re: /(\bunion\b.+\bselect\b|\bor\b\s+\d+\s*=\s*\d+|'\s*or\s*'1'\s*=\s*'1|;\s*drop\s+table|sleep\s*\(|information_schema|--\s*$)/i },
  { type: 'xss',               severity: 'medium',   re: /(<script|javascript:|onerror\s*=|onload\s*=|<iframe|document\.cookie)/i },
  { type: 'path_traversal',    severity: 'high',     re: /(\.\.\/|\.\.\\|%2e%2e|\/etc\/passwd|\/proc\/self|boot\.ini)/i },
  { type: 'command_injection', severity: 'critical', re: /(;\s*(cat|ls|rm|wget|curl|nc|bash|sh)\b|\|\s*(bash|sh)\b|`[^`]+`|\$\([^)]+\))/i },
];

let hit = null;
for (const r of RULES) { if (r.re.test(raw)) { hit = r; break; } }
if (!hit && b.event === 'ssh_failed' && Number(b.failed_count) >= 5)
  hit = { type: 'ssh_brute_force', severity: 'high' };
if (!hit && b.event === 'port_scan' && Number(b.ports_count) >= 10)
  hit = { type: 'port_scan', severity: 'medium' };

const skip = !validIp || WHITELIST.includes(ip);
const detected = !!hit && !skip;

return [{ json: {
  detected, ip,
  attack_type: hit ? hit.type : 'none',
  severity: hit ? hit.severity : 'none',
  path: b.path || '',
  title: hit ? `[${hit.type}] từ ${ip}` : '',
  description: hit ? `IP: ${ip} | Path: ${b.path || '-'} | Payload: ${String(b.payload || '').slice(0, 200)}` : '',
  skipped_reason: skip ? (validIp ? 'whitelist' : 'invalid_ip') : ''
}}];

